mapper.select:
SELECT roomId, roomName, meterMonth, NVL(MAX( DECODE( column_num, 1, preNum ) ), 0) preEleNum, NVL(MAX( DECODE( column_num, 1, curNum ) ), 0) curEleNum, NVL(MAX( DECODE( column_num, 2, preNum ) ), 0) preColdNum, NVL(MAX( DECODE( column_num, 2, curNum ) ), 0) curColdNum, NVL(MAX( DECODE( column_num, 3, preNum ) ), 0) preHotNum, NVL(MAX( DECODE( column_num, 3, curNum ) ), 0) curHotNum FROM ( SELECT t1.ID roomId, nvl( t1.ALIAS_NAME, t1.ROOM_NAME ) roomName, t2.CREATE_TIME meterMonth, NVL(t2.PRE_NUM, 0) preNum, NVL(t2.CUR_NUM, 0) curNum, row_number ( ) over ( partition BY t1.ID, t1.ALIAS_NAME, t1.ROOM_NAME, t2.CREATE_TIME ORDER BY t2.CATEGORY_ID DESC ) column_num FROM SMT_DORMITORY_ROOM t1 LEFT JOIN SMT_SD_METERREADDETAIL_DAILY t2 ON t1.ID = t2.ROOM_ID
AND t1.DORMITORY_ID = #{dormitoryId}
AND t1.FLOOR_ID=#{floorId}
AND t1.ID=#{roomId}
and t2.create_time between to_date(#{startTime},'yyyy-mm-dd hh24:mi:ss') and to_date(#{endTime},'yyyy-mm-dd hh24:mi:ss')
) GROUP BY roomId, roomName, meterMonth ORDER BY roomName ASC
